SourceCode.Declaration:
class TFMLogicStepOperatorDeclareVariable extends TFMLogicBlock implements TFMLogicStepOperatorInterface
{
    TFMFlowVariableName             variableName;
    str                             startValue;
}

Method.Source:
public void new()
{
    super();
    outputs = TFMLogicInputOutputContainer::Construct();        
    outputs.addConnectionName('');

}

public Name blockName()
{
    return variableName ? ("@TFM:Variable" + variableName + (startValue ? '='+startValue : '')) : "@TFM:DeclareVariable";
}

[TFMParameter('')]
public TFMFlowVariableName parmVariableName(TFMFlowVariableName _variableName = variableName)
{
    variableName = _variableName;
    return variableName;
}

[TFMParameter('', "@TFM:Startvalue")]
public Name parmStartValue(Name _startValue = startValue)
{
    startValue = _startValue;
    return startValue;
}

public str runLogic ( TFMRequestElement _request )
{
    _request.logicContext().addFieldContent(variableName, startValue,true);
    _request.makeLogEntry (strFmt('Added variable %1 with the value "%2"', variableName, startValue));
    return '';
}
